class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        # List of (segments, handler, is_static)
        self._routes = []

    def add(self, path, handler):
        segments = path.split('/')
        is_dynamic = any(s.startswith('<') and s.endswith('>') for s in segments)
        self._routes.append((segments, handler, not is_dynamic))

    def _matches(self, route_segments, request_segments):
        if len(route_segments) != len(request_segments):
            return False, None
        params = {}
        for r_seg, req_seg in zip(route_segments, request_segments):
            if r_seg.startswith('<') and r_seg.endswith('>'):
                param_name = r_seg[1:-1]
                if req_seg == "":
                    return False, None
                params[param_name] = req_seg
            else:
                if r_seg != req_seg:
                    return False, None
        return True, params

    def resolve(self, path):
        request_segments = path.split('/')
        best_match = None  # (handler, params, is_static)
        for route_segments, handler, is_static in self._routes:
            matched, params = self._matches(route_segments, request_segments)
            if matched:
                if best_match is None:
                    best_match = (handler, params, is_static)
                else:
                    # Static route wins over dynamic
                    if is_static and not best_match[2]:
                        best_match = (handler, params, is_static)

        if best_match:
            return best_match[0], best_match[1]
        return None, {}

