class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._static_routes = []
        self._dynamic_routes = []

    def add(self, path, handler):
        segments = path.split("/")
        is_dynamic = any(s.startswith("<") and s.endswith(">") for s in segments)
        if is_dynamic:
            self._dynamic_routes.append((segments, handler))
        else:
            self._static_routes.append((path, handler))

    def resolve(self, path):
        segments = path.split("/")
        # Static routes win over dynamic routes regardless of registration order.
        for route_path, handler in self._static_routes:
            if route_path == path:
                return handler, {}

        # Then check dynamic matches (order of registration preserved)
        for route_segments, handler in self._dynamic_routes:
            if len(route_segments) != len(segments):
                continue

            match = True
            params = {}
            for i, route_seg in enumerate(route_segments):
                if route_seg.startswith("<") and route_seg.endswith(">"):
                    param_name = route_seg[1:-1]
                    val = segments[i]
                    if val == "":  # empty segment must not satisfy a parameter
                        match = False
                        break
                    params[param_name] = val
                else:
                    if route_seg != segments[i]:
                        match = False
                        break

            if match:
                return handler, params

        return None, {}

